def label_point(g):
 if QgsWkbTypes.geometryType(g.wkbType())==QgsWkbTypes.PointGeometry:return g.centroid()
 if QgsWkbTypes.geometryType(g.wkbType())==QgsWkbTypes.LineGeometry:return g.interpolate(g.length()/2)
